edits.replacement:
#root .vdet .vstat{ color:var(--tx-2); font-size:16px; }
/* v31.xx (cw-uc-statrows), UI STEP 7 (b-31): the stat rows of the shop, craft and hire detail pane (heals, over, takes) carry an inline 15px size and a cream rule (#ddd5c4) from the paper card days, so on the dark pane they were the brightest lines and under the 16px floor. Now 16px, 6px rows, a --ui-line rule and the value in --tx-1. No words change. */
#root .vdet .vstat[style]{ font-size:16px !important; padding:6px 0 !important; border-bottom:1px solid var(--ui-line) !important; }
#root .vdet .vstat b{ color:var(--tx-1); font-weight:700; }

check:
{v:'VER',what:'detail pane stat rows are 16px with a dark --ui-line rule, not 15px with a cream rule',
 run:function(){
   var r=document.getElementById('root'); if(!r) return 'SKIP: no root';
   var d=document.createElement('div'); d.className='vdet'; d.style.cssText='position:absolute;left:-9999px;top:0';
   d.innerHTML='<div class="vstat" style="font-size:15px;padding:4px 0;border-bottom:1px solid #ddd5c4"><span>a</span><b>b</b></div>';
   r.appendChild(d);
   var cs=getComputedStyle(d.firstChild), fs=cs.fontSize, bc=cs.borderBottomColor, pd=cs.paddingTop;
   d.remove();
   if(fs!=='16px') return 'stat row font is '+fs+', not 16px';
   if(pd!=='6px') return 'stat row padding is '+pd+', not 6px';
   if(bc!=='rgb(46, 51, 55)') return 'stat row rule is '+bc+', not the --ui-line grey';
   return null; }},
